package constructors.class_problems;
public class FareSplitter {double totalFare;int passengerCount;String tripId;FareSplitter(String id,double fare,int count){if(fare<0||count<=0)throw new IllegalArgumentException();tripId=id;totalFare=fare;passengerCount=count;}FareSplitter(String id,double fare){this(id,fare,1);}FareSplitter(String id){this(id,0,2);}double[] fareBreakdown(){double[] r=new double[passengerCount];long cents=Math.round(totalFare*100);long base=cents/passengerCount,rem=cents%passengerCount;for(int i=0;i<passengerCount;i++)r[i]=(base+(i==passengerCount-1?rem:0))/100.0;return r;}boolean isConfirmationOverdue(int confirmed,int expected){return confirmed<expected;}public static void main(String[]a){for(double x:new FareSplitter("TRIP001",100000,3).fareBreakdown())System.out.printf("%.2f ",x);}}